struct Options{std::string input,index,truth,card,summary,events_json,cutflow,efficiencies,process;long events=0;};
Options options(int argc,char**argv){Options o;for(int i=1;i<argc;++i){std::string k=argv[i];require(i+1<argc,"missing option value");std::string v=argv[++i];
  if(k=="--input")o.input=v;else if(k=="--input-index")o.index=v;else if(k=="--truth-index")o.truth=v;else if(k=="--card")o.card=v;else if(k=="--summary")o.summary=v;else if(k=="--events-jsonl")o.events_json=v;else if(k=="--cutflow")o.cutflow=v;else if(k=="--efficiencies")o.efficiencies=v;else if(k=="--process")o.process=v;else if(k=="--events")o.events=std::stol(v);else throw std::runtime_error("unknown argument "+k);}
  require(!o.input.empty()&&!o.index.empty()&&!o.truth.empty()&&!o.card.empty()&&!o.summary.empty()&&!o.events_json.empty()&&!o.cutflow.empty()&&!o.efficiencies.empty()&&o.events>0,"required native analyzer arguments missing");require(o.process=="bbgg"||o.process=="ccgg"||o.process=="jjgg","unknown process");return o;}
std::string sha(const std::string&path){std::ifstream in(path,std::ios::binary);require(in.good(),"cannot hash input file");atlas_hh::Sha256 h;std::array<char,65536>b;while(in.read(b.data(),b.size())||in.gcount())h.update(b.data(),in.gcount());require(in.eof(),"input hash read error");return h.finish();}
void verify_card(const std::string&path){
  std::ifstream file(path,std::ios::binary);std::string text((std::istreambuf_iterator<char>(file)),{});
  const std::string marker="set RandomSeed ";auto pos=text.find(marker);require(pos!=std::string::npos&&text.find(marker,pos+marker.size())==std::string::npos,"ambiguous runtime detector seed");
  auto begin=pos+marker.size(),end=text.find('\n',begin);require(end!=std::string::npos,"truncated runtime card seed");
  const auto seed=text.substr(begin,end-begin);require(!seed.empty()&&seed.find_first_not_of("0123456789")==std::string::npos&&std::stol(seed)>0&&std::stol(seed)<=2147483647,"invalid detector seed");
  text.replace(begin,end-begin,"610301");
  require(atlas_hh::Sha256::digest(text)=="cd91fc7982365af23e4002c6295418fbbc0077ffe381e992e7e6070052eb1f47","native study card definitions differ from reviewed baseline");
}
std::ofstream output(const std::string&path){require(!fs::exists(path),"output exists; cannot overwrite evidence");std::ofstream s(path);require(s.good(),"cannot create analysis output");s<<std::setprecision(17);return s;}
void finite_p4(const TLorentzVector&p){require(std::isfinite(p.Px())&&std::isfinite(p.Py())&&std::isfinite(p.Pz())&&std::isfinite(p.E()),"non-finite native nested four-vector");}
long finite_members(TObject*object){long count=0;TIter it(object->IsA()->GetListOfDataMembers());while(auto*member=dynamic_cast<TDataMember*>(it())){
  const auto type=std::string(member->GetTrueTypeName());if(member->GetOffset()<0||(type!="float"&&type!="Float_t"&&type!="double"&&type!="Double_t"))continue;
  int n=1;for(int d=0;d<member->GetArrayDim();++d){require(member->GetMaxIndex(d)>0&&member->GetMaxIndex(d)<=1000,"unbounded native member array");n*=member->GetMaxIndex(d);}
  const char*base=reinterpret_cast<const char*>(object)+member->GetOffset();for(int i=0;i<n;++i){double v=(type=="float"||type=="Float_t")?reinterpret_cast<const float*>(base)[i]:reinterpret_cast<const double*>(base)[i];require(std::isfinite(v),"non-finite native branch member");++count;}}
  if(auto*j=dynamic_cast<Jet*>(object)){finite_p4(j->Area);finite_p4(j->SoftDroppedJet);finite_p4(j->SoftDroppedSubJet1);finite_p4(j->SoftDroppedSubJet2);for(int i=0;i<5;++i){finite_p4(j->TrimmedP4[i]);finite_p4(j->PrunedP4[i]);finite_p4(j->SoftDroppedP4[i]);}}return count;}
void hash_numeric_members(TObject*object,atlas_hh::Sha256&digest){
  TIter it(object->IsA()->GetListOfDataMembers());std::ostringstream values;values<<std::setprecision(17)<<object->IsA()->GetName()<<' ';
  while(auto*m=dynamic_cast<TDataMember*>(it())){
    std::string type=m->GetTrueTypeName(),name=m->GetName();
    if(m->GetOffset()<0||name=="ReadTime"||name=="ProcTime")continue;
    const bool real_type=type=="float"||type=="Float_t"||type=="double"||type=="Double_t";
    const bool int_type=type=="int"||type=="Int_t"||type=="unsigned int"||type=="UInt_t"||type=="Long64_t"||type=="long long";
    if(!real_type&&!int_type)continue;
    int n=1;for(int d=0;d<m->GetArrayDim();++d)n*=m->GetMaxIndex(d);
    const char*base=reinterpret_cast<const char*>(object)+m->GetOffset();values<<name<<'=';
    for(int i=0;i<n;++i){
      if(type=="float"||type=="Float_t")values<<reinterpret_cast<const float*>(base)[i];
      else if(type=="double"||type=="Double_t")values<<reinterpret_cast<const double*>(base)[i];
      else if(type=="unsigned int"||type=="UInt_t")values<<reinterpret_cast<const unsigned*>(base)[i];
      else if(type=="Long64_t"||type=="long long")values<<reinterpret_cast<const long long*>(base)[i];
      else values<<reinterpret_cast<const int*>(base)[i];
      values<<',';
    }values<<';';
  }
  if(auto*j=dynamic_cast<Jet*>(object)){auto p4=[&](const TLorentzVector&p){values<<p.Px()<<','<<p.Py()<<','<<p.Pz()<<','<<p.E()<<';';};p4(j->Area);p4(j->SoftDroppedJet);p4(j->SoftDroppedSubJet1);p4(j->SoftDroppedSubJet2);for(int i=0;i<5;++i){p4(j->TrimmedP4[i]);p4(j->PrunedP4[i]);p4(j->SoftDroppedP4[i]);}}
  auto text=values.str();digest.update(text.data(),text.size());
}
std::vector<P4> p4s(const std::vector<TruthObject>&objects){std::vector<P4>v;for(const auto&o:objects)v.push_back(o.p);return v;}
struct Object{int index;P4 p;double energy=0;unsigned flavor=0,btag=0;std::set<unsigned>allowed_flavors;double native_pt=0,native_eta=0,native_mass=0;};
std::vector<P4> p4s(const std::vector<Object>&objects){std::vector<P4>v;for(const auto&o:objects)v.push_back(o.p);return v;}
void sort_objects(std::vector<Object>&v){std::stable_sort(v.begin(),v.end(),[](const Object&a,const Object&b){return a.native_pt!=b.native_pt?a.native_pt>b.native_pt:a.index<b.index;});}
void json_objects(std::ostream&out,const std::vector<Object>&v){out<<'[';bool first=true;for(const auto&o:v){if(!first)out<<',';first=false;out<<"{\"index\":"<<o.index<<",\"pt\":"<<o.native_pt<<",\"eta\":"<<o.native_eta<<",\"phi\":"<<double(o.p.phi())<<",\"mass\":"<<o.native_mass<<",\"stored_energy\":"<<o.energy<<",\"flavor\":"<<o.flavor<<",\"btag\":"<<o.btag<<",\"flavor_assessment\":"<<quoted(o.allowed_flavors.empty()?"NOT_APPLICABLE":o.allowed_flavors.size()==1?"DETERMINATE":"UNCERTAIN_FLOAT_BOUNDARY")<<",\"attainable_flavors\":[";bool f=true;for(auto value:o.allowed_flavors){if(!f)out<<',';f=false;out<<value;}out<<"]}";}out<<']';}
void nullable(std::ostream&out,bool exists,long double value){if(exists)out<<double(value);else out<<"null";}
struct Moment{long n=0;long double sum=0,square=0;void add(double x){require(std::isfinite(x),"non-finite response");++n;sum+=x;square+=(long double)x*x;}void json(std::ostream&o)const{o<<"{\"n\":"<<n<<",\"mean\":";if(n)o<<double(sum/n);else o<<"null";o<<",\"population_rms_about_mean\":";if(n)o<<double(std::sqrt(std::max(0.L,square/n-(sum/n)*(sum/n))));else o<<"null";o<<'}';}};
struct Matching{long total=0,fiducial=0,matched=0,fiducial_matched=0,edges=0,amb_truth=0,amb_reco=0;Moment pt_response,energy_response;std::map<int,Moment>pt_binned_energy;};
void fraction_json(std::ostream&out,long selected,long total){if(!total){out<<"null";return;}auto w=wilson(selected,total);out<<"{\"numerator\":"<<selected<<",\"denominator\":"<<total<<",\"estimate\":"<<w.estimate<<",\"wilson95_low\":"<<w.low<<",\"wilson95_high\":"<<w.high<<",\"statistics_status\":"<<quoted(total<30||selected<5||total-selected<5?"INSUFFICIENT_STATISTICS":"DESCRIPTIVE_SUFFICIENT_COUNTS")<<'}';}
void add_match(Matching&s,const std::vector<P4>&truth,const std::vector<Object>&reco,const Match&m,bool photon){s.total+=truth.size();s.matched+=m.pairs.size();s.edges+=m.candidate_edges;s.amb_truth+=m.ambiguous_truth;s.amb_reco+=m.ambiguous_reco;
  for(const auto&p:truth)s.fiducial+=photon?photon_fiducial(p):jet_fiducial(p);
  for(const auto&pair:m.pairs){const auto&t=truth[pair.truth];const auto&r=reco[pair.reco];s.fiducial_matched+=photon?photon_fiducial(t):jet_fiducial(t);require(t.pt()>0&&t.e>0,"invalid truth response denominator");s.pt_response.add(double(r.native_pt/t.pt()));if(photon){double residual=double((r.energy-t.e)/t.e);s.energy_response.add(residual);int bin=0;for(int edge:{25,35,50,75,100,150,250,500})if(t.pt()>=edge)bin=edge;s.pt_binned_energy[bin].add(residual);}}
}
void matching_json(std::ostream&out,const Matching&s){out<<"{\"truth_objects\":"<<s.total<<",\"fiducial_truth_objects\":"<<s.fiducial<<",\"uniquely_matched\":"<<s.matched<<",\"fiducial_truth_matched\":"<<s.fiducial_matched<<",\"candidate_edges\":"<<s.edges<<",\"truth_with_multiple_candidates\":"<<s.amb_truth<<",\"reco_with_multiple_candidates\":"<<s.amb_reco<<",\"matching_fraction_all_truth\":";nullable(out,s.total>0,s.total?double(s.matched)/s.total:0);out<<",\"conditional_fraction_fiducial_truth\":";nullable(out,s.fiducial>0,s.fiducial?double(s.fiducial_matched)/s.fiducial:0);out<<",\"acceptance_fraction\":";fraction_json(out,s.fiducial,s.total);out<<",\"all_truth_matching_fraction_uncertainty\":";fraction_json(out,s.matched,s.total);out<<",\"fiducial_matching_fraction_uncertainty\":";fraction_json(out,s.fiducial_matched,s.fiducial);out<<",\"uncertainty_scope\":\"object-count Wilson diagnostic; same-event correlations are not modeled; not calibrated efficiency\",\"pt_response_reco_over_truth\":";s.pt_response.json(out);out<<",\"photon_energy_fractional_residual_matched_only\":";s.energy_response.json(out);out<<",\"photon_energy_residual_by_truth_pt_lower_edge_gev\":{";bool f=true;for(const auto&[bin,m]:s.pt_binned_energy){if(!f)out<<',';f=false;out<<quoted(std::to_string(bin))<<':';m.json(out);}out<<"}}";}
struct Efficiency{long n=0,k=0;long double expected=0,variance=0;void add(bool tagged,double p){require(p>=0&&p<=1,"tag probability outside unit interval");++n;k+=tagged;expected+=p;variance+=p*(1-p);}};
struct Cut{long n=0;long double w=0,w2=0;void add(double weight){++n;w+=weight;w2+=(long double)weight*weight;}};
struct Summary{long output=-1,read=0,processed=0,invalid=0,finite_fields=0,tuple_duplicates=0,flavor_boundary=0,heavy_associated=0,heavy_unassociated=0,truth_jets=0,negative_reco_jet_mass=0,negative_genjet_mass=0;long double weights=0,absweights=0,weights2=0;long positive=0,negative=0,zero=0;double max_photon_energy_float_difference=0,max_genjet_difference=0,max_negative_mass_square_over_p_square=0;std::string error,input_sha,index_sha,truth_sha,card_sha,scientific_sha;std::map<int,Efficiency>eff;std::map<std::string,Cut>cuts;std::map<std::string,Matching>matching;std::map<std::string,long>photon_migrations,jet_migrations;std::vector<Branch>schema;std::vector<std::pair<std::string,std::string>>inventory;};
void signed_mass_record(Summary&s,const Object&o,bool gen){if(o.native_mass>=0)return;++(gen?s.negative_genjet_mass:s.negative_reco_jet_mass);const auto p2=o.p.x*o.p.x+o.p.y*o.p.y+o.p.z*o.p.z;s.max_negative_mass_square_over_p_square=std::max(s.max_negative_mass_square_over_p_square,double((long double)o.native_mass*o.native_mass/p2));}
std::set<unsigned> expected_flavors(const P4&jet,const std::vector<InputParticle>&particles){
  int definite=-1;std::vector<int>boundary;auto*db=TDatabasePDG::Instance();
  // Jet eta/phi are persisted Float_t. 2e-6 is a conservative angular envelope
  // for their quantization near R0.4 within the parton acceptance. It changes
  // only the explicitly reported allowed set, never permits arbitrary Flavor.
  for(const auto&p:particles){int id=std::abs(p.pid);
    if(p.status==1||p.status==-1||!db->GetParticle(p.pid)||!((id>=1&&id<=5)||id==21)||p.p.pt()<=1||std::abs(p.p.eta())>2.5)continue;
    auto distance=dr(jet,p.p);int priority=id==21?0:id;
    if(distance<.4L-2e-6L)definite=std::max(definite,priority);
    else if(distance<=.4L+2e-6L)boundary.push_back(priority);
  }return possible_flavors(definite,boundary);
}
void verify_truth(TruthEvent&truth,const std::string&process){
  auto check=[](std::vector<TruthObject>&v){std::set<int>ids;for(const auto&o:v){require(o.id>0&&ids.insert(o.id).second&&o.p.e>=0&&o.mass>=0,"invalid/duplicate truth object");}std::sort(v.begin(),v.end(),[](const auto&a,const auto&b){return a.id<b.id;});};
  for(auto*v:{&truth.lhe_photons,&truth.final_photons,&truth.lhe_partons,&truth.hard_partons,&truth.heavy})check(*v);
  for(const auto&o:truth.lhe_photons)require(o.pid==22,"original LHE photon PID mismatch");
  for(const auto&o:truth.final_photons)require(o.pid==22,"final hard-origin photon PID mismatch");
  std::vector<int>flavors;for(const auto&o:truth.lhe_partons)flavors.push_back(o.pid);std::sort(flavors.begin(),flavors.end());
  if(process=="bbgg")require(flavors==std::vector<int>({-5,5}),"bbgg truth process mismatch");
  else if(process=="ccgg")require(flavors==std::vector<int>({-4,4}),"ccgg truth process mismatch");
  else for(int id:flavors)require((std::abs(id)<=3&&id!=0)||id==21,"light-jjgg truth process mismatch");
  std::vector<int>hard;for(const auto&o:truth.hard_partons)hard.push_back(o.pid);std::sort(hard.begin(),hard.end());require(hard==flavors,"post-interface hard parton flavor mismatch");
  for(const auto&o:truth.heavy)require((o.b==0||o.b==1)&&(o.c==0||o.c==1)&&(o.b||o.c),"invalid terminal heavy flags");
}
std::vector<Object> truth_jets(const InputEvent&e){std::vector<fastjet::PseudoJet>v;auto*db=TDatabasePDG::Instance();for(const auto&p:e.particles)if(p.status==1&&db->GetParticle(p.pid)&&std::abs(p.pid)!=12&&std::abs(p.pid)!=14&&std::abs(p.pid)!=16){fastjet::PseudoJet jet(double(p.p.x),double(p.p.y),double(p.p.z),double(p.p.e));jet.set_user_index(p.id);v.push_back(jet);}fastjet::JetDefinition definition(fastjet::antikt_algorithm,.4);fastjet::ClusterSequence sequence(v,definition);auto jets=fastjet::sorted_by_pt(sequence.inclusive_jets(20));std::vector<Object>out;int i=0;for(const auto&j:jets)out.push_back({i++,{j.px(),j.py(),j.pz(),j.e()},j.e(),0,0,{},j.perp(),j.eta(),j.m()});return out;}
