  auto event=a.get<HepMCEvent>("Event");require(event.size()==1&&event[0]->Number==input.number,"native Event.Number identity mismatch");require(event[0]->Weight==float(input.weights[0]),"native Event.Weight float32/source mismatch");
  auto weights=a.get<Weight>("Weight");require(weights.size()==input.weights.size(),"native named-weight value count mismatch");for(std::size_t i=0;i<weights.size();++i)require(weights[i]->Weight==float(input.weights[i]),"native Weight vector float32/source mismatch");
