  std::vector<Object>photons,jets,genjets;int i=0;for(auto*p:a.get<Photon>("Photon")){auto v=polar(p->PT,p->Eta,p->Phi,0);require(p->E>=0,"negative photon energy");s.max_photon_energy_float_difference=std::max(s.max_photon_energy_float_difference,double(std::abs(v.e-p->E)));photons.push_back({i++,v,p->E,0,0,{},p->PT,p->Eta,0});}
