  sort_objects(photons);sort_objects(jets);sort_objects(genjets);auto independent=truth_jets(input);require(independent.size()==genjets.size(),"native GenJet count vs independent stable-visible FastJet mismatch");
  for(std::size_t j=0;j<genjets.size();++j){auto&p=independent[j].p;auto&q=genjets[j].p;double difference=std::max({double(std::abs(p.pt()-q.pt())),double(std::abs(p.eta()-q.eta())),double(std::abs(std::remainder(p.phi()-q.phi(),2*std::acos(-1.L)))),double(std::abs(independent[j].native_mass-genjets[j].native_mass))});s.max_genjet_difference=std::max(s.max_genjet_difference,difference);require(std::abs(p.pt()-q.pt())<=2e-5*std::max(p.pt(),1.L)&&dr(p,q)<2e-5&&std::abs(independent[j].native_mass-genjets[j].native_mass)<=2e-4*std::max(p.e,1.L),"native GenJet vs independent stable clustering disagreement");}
  s.truth_jets+=independent.size();std::vector<Object>eligible,tagged,selected_photons;for(const auto&j:jets)if(jet_fiducial(j.native_pt,j.native_eta)){eligible.push_back(j);if(j.btag&1)tagged.push_back(j);s.eff[flavor_category(j.flavor)].add(j.btag&1,tag_probability(j.flavor,j.native_pt));}for(const auto&p:photons)if(photon_fiducial(p.native_pt,p.native_eta))selected_photons.push_back(p);
  const auto gamma_match=unique_match(p4s(truth.final_photons),p4s(photons),.2),lhe_match=unique_match(p4s(truth.lhe_photons),p4s(photons),.2),jet_match=unique_match(p4s(independent),p4s(jets),.3),parton_match=unique_match(p4s(truth.hard_partons),p4s(jets),.3);
