  for(const auto&h:truth.heavy){bool associated=false;long double best=.4;for(const auto&j:eligible)if(dr(h.p,j.p)<best){best=dr(h.p,j.p);associated=true;}if(associated)++s.heavy_associated;else ++s.heavy_unassociated;}
  s.photon_migrations[std::to_string(truth.final_photons.size())+"->"+std::to_string(photons.size())]++;s.jet_migrations[std::to_string(independent.size())+"->"+std::to_string(jets.size())]++;
